99	// PluginBinDir returns the managed install directory. Binaries (or symlinks)
100	// placed here are auto-discovered by the kubectl-style dispatcher because
101	// main.go prepends this dir to PATH before MaybeRunPlugin runs.
102	func PluginBinDir() (string, error) {
103		parent, err := pluginParentDir()
104		if err != nil {
105			return "", err
106		}
107		return filepath.Join(parent, pluginManagedBinSubdir), nil
108	}
109	
110	// PluginDataDir returns the per-plugin data directory for the given bare name
111	// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
112	// the plugin's responsibility on first use.
113	//
114	// Returns an error for names the dispatcher would never invoke (empty,
115	// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
116	// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
117	// data subtree.
118	func PluginDataDir(name string) (string, error) {
119		if err := validatePluginName(name); err != nil {
120			return "", err
121		}
122		parent, err := pluginParentDir()
123		if err != nil {
124			return "", err
125		}
126		return filepath.Join(parent, pluginManagedDataSubdir, name), nil
127	}
128	
129	// hasTerminalControlChars reports whether s holds a character a terminal acts
130	// on rather than displays.
131	//
132	// Index entries are attacker-influenced by this package's own threat model, and
133	// they are printed straight to the terminal by search, info, and the browse
134	// picker. An escape sequence in a name, description, or repo URL could clear
135	// the line, reposition the cursor, or repaint a row — spoofing the "[official]"
136	// marker, or the repository name in the very confirmation whose job is to say
137	// where the binary comes from. Bidi controls are included because they do the
138	// same thing by reordering rather than escaping.
139	//
140	// Rejected, not stripped: a sanitized value would no longer be the value that
141	// gets used, and the gap between the two is its own bug. Bad rows are dropped
142	// at index load, which is what the catalog already does with invalid entries.
143	func hasTerminalControlChars(s string) bool {
144		return strings.ContainsFunc(s, func(r rune) bool {
145			return unicode.IsControl(r) || unicode.Is(unicode.Bidi_Control, r)
146		})
147	}
