			t.Errorf("missing %q in the diagnosis: %q", want, stderr.String())
		}
	}
	if strings.Contains(stderr.String(), "use --force to replace") {
		t.Errorf("fell through to the already-installed dead end: %q", stderr.String())
	}
}

